import random as _r


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]
    if n == 1:
        return 'D' if opp_last == 'D' else 'C'

    opp_defects = 0
    my_defects = 0
    c_after_opp_c = 0
    d_after_opp_c = 0
    c_after_opp_d = 0
    d_after_opp_d = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1
        if i > 0:
            pm, po = history[i - 1]
            if po == 'C':
                if m == 'C':
                    c_after_opp_c += 1
                else:
                    d_after_opp_c += 1
            else:
                if m == 'C':
                    c_after_opp_d += 1
                else:
                    d_after_opp_d += 1

    opp_def_rate = opp_defects / n

    recent = history[-12:] if n >= 12 else history
    rd = sum(1 for m, o in recent if o == 'D')
    rr = len(recent)

    if rr > 0 and rd >= rr - 1 and rd > 0:
        return 'D'
    if n >= 4 and rd >= 3 and rr >= 6:
        return 'D'

    if opp_def_rate >= 0.6:
        return 'D'

    if opp_def_rate <= 0.12 and n >= 6:
        if my_last == 'D' and opp_last == 'D':
            return 'C'
        return 'C'

    if opp_last == 'D' and my_last == 'D':
        if rd >= 2:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        return 'D'

    if opp_last == 'D':
        if c_after_opp_d > d_after_opp_d:
            return 'D'
        return 'D'

    if opp_last == 'C':
        if d_after_opp_c > c_after_opp_c * 3 and n > 20:
            return 'D'
        if n > 50 and opp_def_rate < 0.25:
            if (n % 7 == 0) and rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    return 'C'

